verus! {

    // append: given a reference to a Vec<i32> `a` and a value `b: i32`,
    // returns a new Vec<i32> `res` such that
    //   1) res.len() == a.len() + 1
    //   2) for all j < a.len(), res[j] == a[j]
    //   3) res[a.len()] == b
    fn append(a: &Vec<i32>, b: i32) -> (res: Vec<i32>)
        ensures
            res.len() == a.len() + 1,
            forall |j: usize| j < a.len() ==> res[j] == a[j],
            res[a.len()] == b
    {
        // Start with an empty vector
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 0;
        // Copy all elements from `a` into `res`
        while i < a.len()
            invariant i <= a.len();
            invariant res.len() == i;
            invariant forall |j: usize| j < i ==> res[j] == a[j];
            decreases a.len() - i;
        {
            res.push(a[i]);
            i = i + 1;
        }
        // Append the new element `b`
        res.push(b);
        // By the loop invariants and the push above, we get exactly:
        //   res.len() == a.len() + 1
        //   forall j < a.len(): res[j] == a[j]
        //   res[a.len()] == b
        res
    }

} // end of `verus!`

